    // 1. Input Validation & Fault Latching
    if (!wa_input.enable || !wa_input.requested_torque_nm || !wa_input.axes || 
        wa_input.axis_count != 3U || !adcs_is_finite_vec3(wa_input.requested_torque_nm)) {
        goto fault_latch;
    }

    // Validate configuration parameters
    for (int i = 0; i < 3; ++i) {
        if (!isfinite(wa_config.wheel_limit_nm[i]) || wa_config.wheel_limit_nm[i] <= 0.0 ||
            !isfinite(wa_config.max_wheel_slew_nm_per_cycle[i]) || wa_config.max_wheel_slew_nm_per_cycle[i] < 0.0) {
            goto fault_latch;
        }
    }
    if (!isfinite(wa_config.release_cycles) || wa_config.release_cycles < 1 || wa_config.release_cycles > 20 ||
        !isfinite(wa_config.restore_cycles) || wa_config.restore_cycles < 1 || wa_config.restore_cycles > 20) {
        goto fault_latch;
    }

    const adcs_vec3_t *req_t = wa_input.requested_torque_nm;
    const adcs_vec3_t axes[3] = { *wa_input.axes, *(wa_input.axes + 1), *(wa_input.axes + 2) };

    // 2. Determine Availability and Orthogonality
    unint32 avail_mask = wa_input.available_mask & 0x7U;
    int available_count = 0;
    for (int i = 0; i < 3; ++i) {
        if ((avail_mask >> i) & 1U) available_count++;
    }

    // Check orthogonality of the three defined axes
    #define ORTHO_EPS 1.0e-8
    double d01 = fabs(adcs_vec3_dot(&axes[0], &axes[1]));
    double d02 = fabs(adcs_vec3_dot(&axes[0], &axes[2]));
    double d12 = fabs(adcs_vec3_dot(&axes[1], &axes[2]));

    if (d01 > ORTHO_EPS || d02 > ORTHO_EPS || d12 > ORTHO_EPS) {
        goto fault_latch;
    }

    // Normalize axes locally for calculation
    adcs_vec3_t norm_axes[3];
    for(int i=0; i<3; ++i) {
        adcs_vec3_normalize(&axes[i], 1.0e-12, &norm_axes[i]);
    }

    // 3. Handle Disable/Reset
    if (!wa_input.enable) {
        wa_state.mode = WA_NORMAL;
        wa_state.clean_count = 0;
        wa_state.restore_count = 0;
        wa_state.previous_wheel_torque_nm[0] = 0.0;
        wa_state.previous_wheel_torque_nm[1] = 0.0;
        wa_state.previous_wheel_torque_nm[2] = 0.0;
        wa_output.mode = WA_NORMAL;
        wa_output.saturation_mask = 0U;
        wa_output.slew_mask = 0U;
        wa_output.unavailable_mask = 0U;
        wa_output.wheel_torque_nm[0] = 0.0;
        wa_output.wheel_torque_nm[1] = 0.0;
        wa_output.wheel_torque_nm[2] = 0.0;
        wa_output.achieved_torque_nm = (adcs_vec3_t){0,0,0};
        wa_output.residual_torque_nm = (adcs_vec3_t){0,0,0};
        wa_output.residual_norm_nm = 0.0;
        return;
    }

    // 4. Allocation Loop
    unint32 sat_mask = 0U;
    unint32 slew_mask = 0U;
    unint32 unavail_mask = (~avail_mask) & 0x7U;
    adcs_vec3_t achieved = (adcs_vec3_t){0,0,0};
    int any_limit_hit = 0;

    for (int i = 0; i < 3; ++i) {
        double cmd_val = 0.0;
        int is_avail = ((avail_mask >> i) & 1U);

        if (!is_avail) {
            cmd_val = 0.0;
        } else {
            // Ideal projection: - (Req . Axis)
            double proj = -adcs_vec3_dot(req_t, &norm_axes[i]);

            // Apply Magnitude Limit
            double mag_lim = wa_config.wheel_limit_nm[i];
            if (proj > mag_lim) {
                proj = mag_lim;
                sat_mask |= (1U << i);
                any_limit_hit = 1;
            } else if (proj < -mag_lim) {
                proj = -mag_lim;
                sat_mask |= (1U << i);
                any_limit_hit = 1;
            }

            // Apply Slew Limit
            double prev_val = wa_state.previous_wheel_torque_nm[i];
            double diff = proj - prev_val;
            double slew_lim = wa_config.max_wheel_slew_nm_per_cycle[i];

            if (diff > slew_lim) {
                proj = prev_val + slew_lim;
                slew_mask |= (1U << i);
                any_limit_hit = 1;
            } else if (diff < -slew_lim) {
                proj = prev_val - slew_lim;
                slew_mask |= (1U << i);
                any_limit_hit = 1;
            }

            cmd_val = proj;

            // Accumulate achieved torque
            adcs_vec3_t term = adcs_vec3_scale(&norm_axes[i], cmd_val);
            achieved = adcs_vec3_add(&achieved, &term);
        }

        wa_output.wheel_torque_nm[i] = cmd_val;
    }

    // 5. State Machine Transitions
    wa_mode_t next_mode = wa_state.mode;

    if (any_limit_hit) {
        next_mode = WA_LIMITED;
        wa_state.clean_count = 0;
        wa_state.restore_count = 0;
    } else {
        // No limits hit this cycle
        if (wa_state.mode == WA_LIMITED) {
            wa_state.clean_count++;
            if (wa_state.clean_count >= wa_config.release_cycles) {
                next_mode = WA_NORMAL;
                wa_state.clean_count = 0;
            }
        } else if (wa_state.mode == WA_DEGRADED) {
            if (available_count == 3) {
                next_mode = WA_RECOVERING;
                wa_state.restore_count = 0;
            }
        } else if (wa_state.mode == WA_RECOVERING) {
            if (available_count == 3) {
                wa_state.restore_count++;
                if (wa_state.restore_count >= wa_config.restore_cycles) {
                    next_mode = WA_NORMAL;
                    wa_state.restore_count = 0;
                }
            } else {
                // Missing wheel during recovery
                next_mode = WA_DEGRADED;
                wa_state.restore_count = 0;
            }
        } else {
            // Already NORMAL or other safe states with no limits
            next_mode = WA_NORMAL;
            wa_state.clean_count = 0;
            wa_state.restore_count = 0;
        }
    }

    // Handle Degraded state for missing wheels (takes precedence unless in LIMITED/FAULT)
    if (!any_limit_hit && wa_state.mode != WA_FAULT) {
        if (available_count < 3) {
            next_mode = WA_DEGRADED;
            wa_state.clean_count = 0;
            wa_state.restore_count = 0;
        }
    }

    wa_state.mode = next_mode;

    // 6. Final Output Assignment
    wa_output.mode = wa_state.mode;
    wa_output.saturation_mask = sat_mask;
    wa_output.slew_mask = slew_mask;
    wa_output.unavailable_mask = unavail_mask;
    wa_output.achieved_torque_nm = achieved;
    wa_output.residual_torque_nm = adcs_vec3_sub(req_t, &achieved);
    wa_output.residual_norm_nm = adcs_vec3_norm(&wa_output.residual_torque_nm);

    return;

