    double max_slew = wa_config.max_wheel_slew_nm_per_cycle[i];

    int slew_limited = 0;
    if (delta > max_slew) {
        proj = prev + max_slew;
        slew_limited = 1;
    } else if (delta < -max_slew) {
        proj = prev - max_slew;
        slew_limited = 1;
    }
