    // Project requested torque onto wheel axis
    double proj = adcs_vec3_dot(&norm_axes[i], wa_input.requested_torque_nm);

    // Apply Magnitude Limit
    int saturated = 0;
    if (proj > wa_config.wheel_limit_nm[i]) {
        proj = wa_config.wheel_limit_nm[i];
        saturated = 1;
    } else if (proj < -wa_config.wheel_limit_nm[i]) {
        proj = -wa_config.wheel_limit_nm[i];
        saturated = 1;
    } else {
        /* Within magnitude limits */
    }
    if (saturated) sat_mask |= (1 << i);

    // Apply Slew Limit
    double prev = wa_state.previous_wheel_torque_nm[i];
    double delta = proj - prev;
    double max_slew = wa_config.max_wheel_slew_nm_per_cycle[i];

    int slew_limited = 0;
    if (delta > max_slew) {
        proj = prev + max_slew;
        slew_limited = 1;
    } else if (delta < -max_slew) {
        proj = prev - max_slew;
        slew_limited = 1;
    } else {
        /* Within slew limits */
    }
    if (slew_limited) slew_mask |= (1 << i);

    wa_output.wheel_torque_nm[i] = proj;

    // Accumulate Achieved Torque
    adcs_vec3_t contrib = adcs_vec3_scale(&norm_axes[i], proj);
    achieved = adcs_vec3_add(&achieved, &contrib);

    if (saturated || slew_limited) any_limited = 1;
