    return;
}

// Step 4: State Machine Logic & Allocation
unint32 current_saturation_mask = 0;
unint32 current_slew_mask = 0;
unint32 current_unavailable_mask = 0;

// Initialize achieved torque to zero
wa_output.achieved_torque_nm.x = 0.0;
wa_output.achieved_torque_nm.y = 0.0;
wa_output.achieved_torque_nm.z = 0.0;

double prev_wheels[3];
for(int i=0; i<3; i++) prev_wheels[i] = wa_state.previous_wheel_torque_nm[i];

// Allocation Loop
for (int i = 0; i < 3; i++) {
    if (!((available_mask >> i) & 1)) {
        // Unavailable
        wa_output.wheel_torque_nm[i] = 0.0;
        current_unavailable_mask |= (1U << i);
        continue;
    }

    const adcs_vec3_t *axis = &valid_axes[i];

    // Allocate -axis dot requested spacecraft torque
    double proj = -adcs_vec3_dot(axis, wa_input.requested_torque_nm);

    // Apply Magnitude Limit
    double min_lim = -wa_config.wheel_limit_nm[i];
    double max_lim = wa_config.wheel_limit_nm[i];
    double limited_mag = proj;
    if (proj < min_lim) {
        limited_mag = min_lim;
        current_saturation_mask |= (1U << i);
    } else if (proj > max_lim) {
        limited_mag = max_lim;
        current_saturation_mask |= (1U << i);
    }

    // Apply Slew Limit
    double delta = limited_mag - prev_wheels[i];
    double max_slew = wa_config.max_wheel_slew_nm_per_cycle[i];
    double min_slew = -max_slew;

    if (delta < min_slew) {
        delta = min_slew;
        current_slew_mask |= (1U << i);
    } else if (delta > max_slew) {
        delta = max_slew;
        current_slew_mask |= (1U << i);
    }

    double new_torque = prev_wheels[i] + delta;
    wa_output.wheel_torque_nm[i] = new_torque;

    // Accumulate Achieved Torque
    adcs_vec3_t t_comp = adcs_vec3_scale(axis, new_torque);
    wa_output.achieved_torque_nm.x += t_comp.x;
    wa_output.achieved_torque_nm.y += t_comp.y;
    wa_output.achieved_torque_nm.z += t_comp.z;

    prev_wheels[i] = new_torque;
}

// Update State based on masks
if (wa_output.mode == WA_RECOVERING) {
    // If any wheel is unavailable during recovery, go to DEGRADED
    if (current_unavailable_mask != 0) {
        wa_output.mode = WA_DEGRADED;
        wa_output.clean_count = 0;
        wa_output.restore_count = 0;
    } else {
        // All wheels available. Check for saturation/slew
        if (current_saturation_mask == 0 && current_slew_mask == 0) {
            wa_output.restore_count++;
        } else {
            wa_output.restore_count = 0;
        }

        if (wa_output.restore_count >= wa_config.restore_cycles) {
            wa_output.mode = WA_NORMAL;
            wa_output.clean_count = 0;
            wa_output.restore_count = 0;
        }
    }
} else if (wa_output.mode == WA_LIMITED) {
    if (current_saturation_mask == 0 && current_slew_mask == 0) {
        wa_output.clean_count++;
    } else {
        wa_output.clean_count = 0;
    }

    if (wa_output.clean_count >= wa_config.release_cycles) {
        wa_output.mode = WA_NORMAL;
        wa_output.clean_count = 0;
    }
}
// For NORMAL, DEGRADED, FAULT, mode remains unchanged unless transitioned above

// Save state for next cycle
